begin;
do $test$
declare u1 uuid:=gen_random_uuid();u2 uuid:=gen_random_uuid();p1 uuid:=gen_random_uuid();p2 uuid:=gen_random_uuid();f1 uuid:=gen_random_uuid();f2 uuid:=gen_random_uuid();fn uuid:=gen_random_uuid();n integer;
begin
 perform set_config('request.jwt.claim.role','service_role',true);
 insert into auth.users(id,email,aud,role) values(u1,u1||'@example.test','authenticated','authenticated'),(u2,u2||'@example.test','authenticated','authenticated');
 update public.profiles set role='chef',is_owner=false where id in(u1,u2);
 insert into public.projets(id,nom,owner_id) values(p1,'Synthetic hotfix A',u1),(p2,'Synthetic hotfix B',u2);
 insert into public.figurants(id,prenom,nom,est_comedien,comedien_pool_id,acces_compte) values(f1,'Private','Own',true,u1,false),(f2,'Private','Foreign',true,u2,true),(fn,'Private','Null',true,null,true);
 insert into public.partage_liens(projet_id,type,token) values(p1,'casting','synthetic-share-own-'||p1),(p2,'casting','synthetic-share-foreign-'||p2);
 insert into public.figurant_sessions(figurant_id,token,expires_at) values(f2,'synthetic-session-'||f2,now()+interval '1 hour');
 update public.profiles set gmail_smtp_app_password='SYNTHETIC-SECRET-ONLY' where id=u2;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u1,'role','authenticated')::text,true);
 perform set_config('request.jwt.claim.role','authenticated',true);
 set local role authenticated;
 select count(*) into n from public.figurants where id=f1;assert n=1,'Own comedian without account hidden';
 select count(*) into n from public.figurants where id in(f2,fn);assert n=0,'Foreign/null comedian leaked';
 select count(*) into n from public.partage_liens where projet_id=p1;assert n=1,'Own share hidden';
 select count(*) into n from public.partage_liens where projet_id=p2;assert n=0,'Foreign share token leaked';
 begin update public.figurants set nom='forged' where id=f2;raise exception using errcode='ZX002',message='Direct figurant UPDATE allowed';exception when insufficient_privilege then null;end;
 begin delete from public.figurants where id=f2;raise exception using errcode='ZX002',message='Direct figurant DELETE allowed';exception when insufficient_privilege then null;end;
 begin select count(*) into n from public.figurant_sessions;assert n=0,'Session token leaked';exception when insufficient_privilege then null;end;
 begin perform public.delete_unused_figurant(f2);raise exception using errcode='ZX002',message='Non-owner delete RPC allowed';exception when insufficient_privilege then null;end;
 begin perform gmail_smtp_app_password from public.profiles where id=u2;raise exception using errcode='ZX002',message='Foreign SMTP secret readable';exception when insufficient_privilege then null;end;
 begin perform gmail_smtp_app_password from public.profiles where id=u1;raise exception using errcode='ZX002',message='Own SMTP secret exposed to browser';exception when insufficient_privilege then null;end;
 assert not has_table_privilege('authenticated','public.profiles','TRUNCATE'),'Profiles TRUNCATE allowed';
 assert not has_table_privilege('authenticated','public.figurants','TRUNCATE'),'Figurants TRUNCATE allowed';
 assert not has_column_privilege('anon','public.profiles','gmail_smtp_app_password','SELECT'),'Anonymous SMTP grant';
 select count(*) into n from public.profiles where id in(u1,u2);assert n=2,'Team names hidden';
 perform id, nom, prenom, telephone, role, avatar_storage_path, last_seen_at, sections_autorisees, is_owner, comedien_pool_id, acces_complet from public.profiles where id=u1;
 perform gmail_smtp_user, email_espace_perso_template, email_magic_link_template from public.profiles where id=u1;
 update public.profiles set nom='Self edit allowed',last_seen_at=now() where id=u1;
 raise notice 'PASS: SMTP secret denied for self/foreign/anon; team and login fields/self-edit preserved; TRUNCATE denied';
 reset role;
 perform set_config('request.jwt.claim.role','service_role',true);set local role service_role;
 assert (select gmail_smtp_app_password='SYNTHETIC-SECRET-ONLY' from public.profiles where id=u2),'Service SMTP read broken';
 update public.profiles set gmail_smtp_app_password='SYNTHETIC-SERVICE-UPDATE' where id=u2;
 assert (select gmail_smtp_app_password='SYNTHETIC-SERVICE-UPDATE' from public.profiles where id=u2),'Service SMTP update broken';reset role;
 assert exists(select 1 from public.figurants where id=f2 and nom='Foreign'),'Foreign profile modified';
 perform set_config('request.jwt.claims','{"role":"anon"}',true);perform set_config('request.jwt.claim.role','anon',true);set local role anon;
 begin select count(*) into n from public.figurants;assert n=0,'Anonymous figurants visible';exception when insufficient_privilege then null;end;
 begin select count(*) into n from public.partage_liens;assert n=0,'Anonymous share tokens visible';exception when insufficient_privilege then null;end;
 reset role;
 raise notice 'PASS: private pools, own access, direct write denials, share isolation, sessions, deletion RPC, anon';
end $test$;
rollback;
